r\",\n      \"reason\": \"Modeled and operated a PostgreSQL clinical reporting warehouse and improved its load orchestration.\",\n      \"evidence_ids\": [\"ctx-d88634a9\", \"b-e29dcd09\", \"b-1dcc4784\"],\n      \"lane\": \"specialist\"\n    },\n    {\n      \"title\": \"Analytics Engineer\",\n      \"reason\": \"Reporting pipeline delivery and dimensional modeling support this previously held role family.\",\n      \"evidence_ids\": [\"ctx-5de0aefc\", \"b-65d51321\", \"skl-717db87c\"],\n      \"lane\": \"specialist\"\n    }\n  ],\n  \"archetypes\": [\n    {\n      \"name\": \"Organisations with shared data platforms serving analytics and compliance teams\",\n      \"because\": \"Platform work involved analytics and compliance on schema changes, with a lineage service adopted by four downstream teams.\",\n      \"evidence_ids\": [\"ctx-dc4ff440\", \"b-c58f7191\"]\n    },\n    {\n      \"name\": \"Organisations integrating many source feeds into governed data infrastructure\",\n      \"because\": \"The record combines Kafka ingestion across 212 feeds with schema compatibility controls and column-level quality rules.\",\n      \"evidence_ids\": [\"b-b279601d\", \"b-f64b391d\", \"b-636c4345\"]\n    },\n    {\n      \"name\": \"Healthcare organisations operating clinical reporting warehouses\",\n      \"because\": \"Ran a clinical reporting warehouse and worked with analysts and clinicians on definitions.\",\n      \"evidence_ids\": [\"ctx-d88634a9\", \"b-e29dcd09\"]\n    },\n    {\n      \"name\": \"Operational businesses replacing spreadsheet reporting with automated pipelines\",\n      \"because\": \"Built a freight brokerage's first automated reporting pipeline to replace spreadsheets shared by email.\",\n      \"evidence_ids\": [\"ctx-5de0aefc\", \"b-65d51321\"]\n    }\n  ],\n  \"capabilities\": [\n    {\n      \"name\": \"Streaming ingestion engineering\",\n      \"terms\": [\"Kafka\", \"streaming ingestion\", \"ingestion pipelines\", \"source feeds\", \"low-late